/* eslint-disable @typescript-eslint/no-unused-vars */
/* eslint-disable @typescript-eslint/no-unused-expressions */

import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent } from 'react';
import QRCode from 'qrcode';
import { db } from './lib/db';
import { clearDemoData, loadDemoData } from './lib/demo';
import { createBackup, exportCsv, exportExcel, exportFilteredHistory, restoreBackup } from './lib/export';
import { downloadCloudBackup, subscribeRealtime, syncNow, uploadCloudBackup } from './lib/sync';
import type { Location, Movement, Pallet, Parcel, Permission, Profile, Reception, Role } from './lib/types';
import { assignExtractionTasks, closePallet, closeReception, createLocation, createReception, extractPallet, locatePallet, moveTaskToFloor, reopenPallet, scanParcel, setExpectedParcels, unlockReceptionForExtraction, updateReception } from './lib/warehouse';
import { defaultBarcodeRule, parseBoxBarcode, planPallets, readBarcodeRule, refreshBarcodeRule, saveBarcodeRule } from './lib/barcodes';
import { apiUrl } from './lib/api';
import { HistoryExplorerV3 } from './components/HistoryExplorer';
import { AdvancedPlanner } from './components/AdvancedPlanner';
import { SecureSignIn } from './components/SecureSignIn';

const scanFeedback=(kind:'ok'|'anomaly'|'complete')=>{if(typeof navigator!=='undefined'&&navigator.vibrate)navigator.vibrate(kind==='ok'?60:kind==='complete'?[80,60,160]:[180,80,180]);try{const context=new AudioContext();const oscillator=context.createOscillator();oscillator.frequency.value=kind==='ok'?880:kind==='complete'?1100:220;oscillator.connect(context.destination);oscillator.start();oscillator.stop(context.currentTime+.12)}catch{}};
const readOcrFile=async(file:File)=>{const {recognize}=await import('tesseract.js');const result=await recognize(file,'eng',{logger:()=>undefined});return (result.data.text.match(/[0-9]{8,}/g)||[]).sort((a,b)=>b.length-a.length)[0]||''};

type View = 'inicio'|'recepciones'|'etiquetas'|'escanear'|'ubicar'|'tareas'|'extraer'|'inventario'|'movimientos'|'datos'|'usuarios';
type Snapshot = { receptions:Reception[]; pallets:Pallet[]; parcels:Parcel[]; locations:Location[]; movements:Movement[]; pending:number };
const empty:Snapshot={receptions:[],pallets:[],parcels:[],locations:[],movements:[],pending:0};
const nav:Array<[View,string,string]>=[['inicio','⌂','Inicio'],['recepciones','▣','Recepciones'],['etiquetas','QR','Etiquetas'],['escanear','▦','Escanear'],['ubicar','⌖','Ubicar'],['tareas','☑','Tareas'],['extraer','↗','Extraer'],['inventario','☷','Inventario'],['movimientos','↔','Movimientos'],['datos','⇅','Datos']];
const allPermissions:Permission[]=['recepciones','escanear','ubicar','extraer','inventario','exportar','usuarios','reglas','corregir','restaurar'];
const viewPermission:Partial<Record<View,Permission>>={recepciones:'recepciones',etiquetas:'recepciones',escanear:'escanear',ubicar:'ubicar',tareas:'extraer',extraer:'extraer',inventario:'inventario',datos:'exportar',usuarios:'usuarios'};

export default function Home(){
  const [view,setView]=useState<View>('inicio');const [data,setData]=useState(empty);const [online,setOnline]=useState(()=>typeof navigator==='undefined'||navigator.onLine);const [dark,setDark]=useState(false);
  const [profile,setProfile]=useState<Profile|null>(null);const [authLoading,setAuthLoading]=useState(true);const [notice,setNotice]=useState<{kind:'ok'|'error';text:string}|null>(null);const [busy,setBusy]=useState(false);
  const [labelReceptionId,setLabelReceptionId]=useState('');
  const refresh=useCallback(async()=>setData({receptions:(await db.receptions.toArray()).filter(x=>!x.deletedAt),pallets:(await db.pallets.toArray()).filter(x=>!x.deletedAt),parcels:(await db.parcels.toArray()).filter(x=>!x.deletedAt),locations:(await db.locations.toArray()).filter(x=>!x.deletedAt),movements:(await db.movements.orderBy('createdAt').reverse().toArray()).filter(x=>!x.deletedAt),pending:await db.operations.count()}),[]);
  const tell=useCallback((text:string,kind:'ok'|'error'='ok')=>{setNotice({text,kind});window.setTimeout(()=>setNotice(null),4000)},[]);
  useEffect(()=>{const on=()=>setOnline(true),off=()=>setOnline(false);addEventListener('online',on);addEventListener('offline',off);queueMicrotask(()=>void refresh());
    queueMicrotask(()=>{void fetch(apiUrl('/api/session'),{credentials:'include'}).then(async response=>{if(!response.ok)return null;return (await response.json() as {profile:Profile}).profile}).then(found=>{setProfile(found);if(found&&navigator.onLine)void syncNow().then(refresh).catch(()=>undefined)}).catch(()=>setProfile(null)).finally(()=>setAuthLoading(false))});
    if('serviceWorker'in navigator){
      if(import.meta.env.PROD)navigator.serviceWorker.register(`${import.meta.env.BASE_URL||'/'}sw.js`).catch(()=>undefined);
      else navigator.serviceWorker.getRegistrations().then((items)=>Promise.all(items.map((item)=>item.unregister()))).catch(()=>undefined);
    }
    return()=>{removeEventListener('online',on);removeEventListener('offline',off)};
  },[refresh]);
  useEffect(()=>{if(!profile||!online)return;let syncing=false;return subscribeRealtime(()=>{if(syncing)return;syncing=true;void syncNow().then(refresh).finally(()=>{syncing=false})})},[profile,online,refresh]);
  const can=(permission:Permission)=>profile?.role==='manager'||profile?.permissions.includes(permission);
  const go=(next:View)=>{const permission=viewPermission[next];if(permission&&!can(permission)){tell('Tu perfil no tiene permiso para esta función.','error');return;}setView(next)};
  const perform=async(action:()=>Promise<unknown>,success:string)=>{setBusy(true);try{await action();await refresh();if(online&&profile)await syncNow();await refresh();tell(success)}catch(error){tell(error instanceof Error?error.message:'No se pudo completar la operación.','error')}finally{setBusy(false)}};
  if(authLoading)return <div className="auth-screen"><div className="loader"/><h1>PalletFlow Almacén</h1><p>Preparando tu zona de trabajo…</p></div>;
  if(!profile)return <SecureSignIn/>;
  if(profile.status!=='active')return <PendingAccess profile={profile}/>;
  const activePallets=data.pallets.filter(p=>p.status!=='extraido');
  const desktopNav=(profile.role==='admin'||profile.role==='manager')?nav:nav.filter(([id])=>['inicio','recepciones','escanear','ubicar','tareas'].includes(id));
  const mobileNav=((profile.role==='admin'||profile.role==='manager')?['inicio','recepciones','inventario','datos']:['inicio','escanear','ubicar','tareas']).map(id=>nav.find(item=>item[0]===id)!).filter(Boolean);

  return <div className={`${dark?'app-shell dark':'app-shell'} role-${profile.role}`}>
    <div className="safety-stripe" aria-hidden="true"/>
    <header className="topbar"><div><p className="eyebrow">PALLETFLOW</p><h1>Control de almacén</h1></div><div className="top-actions"><span className={`connection ${online?'is-online':''}`}><i/> {online?'Online':'Sin conexión'} · {data.pending?`${data.pending} por subir`:'todo guardado'}</span><button className="operator" title="Cambiar operario" onClick={()=>{void fetch(apiUrl('/api/session'),{method:'DELETE',credentials:'include'}).finally(()=>{localStorage.removeItem('palletflow-operator-name');setProfile(null)})}}>OP <strong>{profile.displayName}</strong><small>{profile.role} · cambiar</small></button></div></header>
    <div className="test-banner operational" role="status"><span>✓</span> ACCESO OPERATIVO · CAMBIOS SINCRONIZADOS EN LA NUBE</div>
    <nav className="main-nav" aria-label="Navegación principal">{desktopNav.map(([id,,label])=><button key={id} className={view===id?'active':''} onClick={()=>go(id)}>{label}</button>)}</nav>
    {notice&&<div className={`toast ${notice.kind}`} role="status">{notice.kind==='ok'?'✓':'!'} {notice.text}</div>}
    <main>
      {view==='inicio'&&<Dashboard data={data} go={go} dark={dark} setDark={setDark} online={online} profile={profile} sync={()=>perform(()=>syncNow(),'Información subida y actualizada.')}/>}
      {view==='recepciones'&&<><Receptions data={data} busy={busy} create={async(input)=>{setBusy(true);try{const reception=await createReception(input,profile.displayName);await refresh();setLabelReceptionId(reception.id);setView('etiquetas');tell('Recepción creada. Las etiquetas QR están listas para imprimir.')}catch(error){tell(error instanceof Error?error.message:'No se pudo crear la recepción.','error')}finally{setBusy(false)}}} openLabels={(id)=>{setLabelReceptionId(id);setView('etiquetas')}} close={(id)=>{if(confirm('¿Cerrar y bloquear este camión?'))void perform(()=>closeReception(id),'Camión cerrado y bloqueado.')}}/>{(profile.role==='admin'||profile.role==='manager')&&<ReceptionControl receptions={data.receptions} pallets={data.pallets} locations={data.locations} operator={profile.displayName} act={(action,message)=>perform(action,message)}/>}</>}
      {view==='etiquetas'&&<LabelsView receptions={data.receptions} pallets={data.pallets} selectedId={labelReceptionId} onSelect={setLabelReceptionId}/>}
      {view==='escanear'&&<GuidedScanner pallets={activePallets.filter(p=>!p.scanClosedAt)} parcels={data.parcels} busy={busy} operator={profile.displayName} refresh={refresh} tell={tell}/>} 
      {view==='ubicar'&&<LocationsView pallets={activePallets.filter(p=>p.scanClosedAt&&p.status!=='ubicado'&&p.status!=='en_suelo')} locations={data.locations} busy={busy} locate={(p,l)=>perform(()=>locatePallet(p,l,profile.displayName),'Palé ubicado correctamente.')} create={(input)=>perform(()=>createLocation(input),'Ubicación creada.')}/>} 
      {view==='tareas'&&<TasksView pallets={data.pallets} locations={data.locations} operator={profile.displayName} busy={busy} complete={(p,l,pc,c)=>perform(()=>moveTaskToFloor(p,l,pc,c,profile.displayName),'Tarea completada. Palé registrado en suelo.')}/>} 
      {view==='extraer'&&<Extraction pallets={activePallets.filter(p=>p.parcels>0)} busy={busy} extract={(p,c,r)=>perform(()=>extractPallet(p,c,r,profile.displayName),'Extracción registrada.')}/>} 
      {view==='inventario'&&<><AdvancedPlanner pallets={data.pallets} locations={data.locations}/><Inventory pallets={data.pallets} receptions={data.receptions} locations={data.locations}/>{(profile.role==='admin'||profile.role==='manager')&&<AdminOrdersPanel pallets={data.pallets} locations={data.locations} operator={profile.displayName} act={(ids,assignee)=>perform(()=>assignExtractionTasks(ids,assignee,profile.displayName),'Orden de extracción creada.')}/>}</>} 
      {view==='movimientos'&&<><HistoryExplorerV3 receptions={data.receptions} pallets={data.pallets} parcels={data.parcels} locations={data.locations}/><MovementsView movements={data.movements} pallets={data.pallets} locations={data.locations}/></>}
      {view==='datos'&&<><CloudBackupPanel onRefresh={refresh} tell={tell}/>{(profile.role==='admin'||profile.role==='manager')&&<><BarcodeSettings tell={tell}/><DataView busy={busy} pending={data.pending} onRefresh={refresh} tell={tell}/></>}</>}
    </main>
    <nav className="mobile-nav" aria-label="Navegación móvil">{mobileNav.map(([id,icon,label])=><button className={view===id?'active':''} onClick={()=>go(id)} key={id}><span>{icon}</span>{label}</button>)}</nav>
  </div>;
}

function SignIn(){const [name,setName]=useState(()=>typeof localStorage==='undefined'?'':localStorage.getItem('palletflow-operator-name')||'');const [pin,setPin]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const manager=name.trim().toLocaleLowerCase('es')==='ayyoub';const enter=async(e:FormEvent)=>{e.preventDefault();const clean=name.trim();if(clean.length<2)return;setBusy(true);setError('');try{const response=await fetch(apiUrl('/api/session'),{method:'POST',credentials:'include',headers:{'content-type':'application/json'},body:JSON.stringify({name:clean,pin:manager?pin:undefined})});const body=await response.json() as {error?:string};if(!response.ok)throw new Error(body.error||'No se pudo entrar.');localStorage.setItem('palletflow-operator-name',clean);location.reload()}catch(reason){setError(reason instanceof Error?reason.message:'No se pudo entrar.');setBusy(false)}};return <div className="auth-screen"><form className="auth-card" onSubmit={e=>void enter(e)}><p className="eyebrow">PALLETFLOW</p><h1>¿Quién trabaja ahora?</h1><p>Los operarios entran solo con su nombre. Ayyoub utiliza además su PIN de administrador.</p><Field label="Nombre del operario"><input autoFocus required minLength={2} autoComplete="name" value={name} onChange={e=>{setName(e.target.value);setError('')}} placeholder="Ej. Manuel"/></Field>{manager&&<Field label="PIN de administrador"><input required inputMode="numeric" type="password" autoComplete="current-password" value={pin} onChange={e=>setPin(e.target.value)} placeholder="••••"/></Field>}{error&&<p className="camera-error">{error}</p>}<button disabled={busy||!name.trim()||(manager&&!pin)} className="primary-button wide">{busy?'Comprobando…':'Entrar al almacén'}</button><small>No utiliza correo ni una cuenta de ChatGPT.</small></form></div>}
function PendingAccess({profile}:{profile:Profile}){return <div className="auth-screen"><div className="auth-card"><span className="big-state">⏳</span><h1>Acceso pendiente</h1><p>Hola, {profile.displayName}. Un manager debe activar tu perfil antes de que puedas operar.</p><a className="secondary-button button-link" href="/signout-with-chatgpt?return_to=%2F">Salir</a></div></div>}

function Dashboard({data,go,dark,setDark,online,profile,sync}:{data:Snapshot;go:(v:View)=>void;dark:boolean;setDark:(v:boolean)=>void;online:boolean;profile:Profile;sync:()=>void}){
  const today=new Date().toISOString().slice(0,10);const stats=[['Recepciones abiertas',data.receptions.filter(r=>!['cerrada','completada'].includes(r.status)).length,'Activas ahora'],['Palés por escanear',data.pallets.filter(p=>p.status==='pendiente').length,'Pendientes'],['Palés por ubicar',data.pallets.filter(p=>p.status==='escaneado').length,'Requieren acción'],['Palés ubicados',data.pallets.filter(p=>p.status==='ubicado').length,'En inventario'],['Bultos totales',data.pallets.reduce((a,p)=>a+p.parcels,0),'Registrados'],['Unidades totales',data.pallets.reduce((a,p)=>a+p.units,0),'Disponibles'],['Movimientos hoy',data.movements.filter(m=>m.createdAt.startsWith(today)).length,'Actividad'],['Cambios locales',data.pending,online?'Listos para enviar':'Esperando conexión']];
  const actions:Array<[string,string,string,View]>=[['＋','Nueva recepción','Crear descarga','recepciones'],['▦','Escanear palé','Registrar bultos','escanear'],['⌖','Ubicar palé','Asignar hueco','ubicar'],(profile.role==='admin'||profile.role==='manager')?['↗','Preparar pedido','Crear misiones','inventario']:['☑','Mis tareas','Seguir extracciones','tareas']];
  return <><section className="welcome-row"><div><p className="section-kicker">{profile.role.toUpperCase()} · {new Intl.DateTimeFormat('es-ES',{dateStyle:'medium'}).format(new Date())}</p><h2>¿Qué necesitas hacer?</h2><p className="muted">Acciones habituales, siempre a un toque.</p></div><div className="row-actions"><button className="secondary-button" onClick={()=>setDark(!dark)}>{dark?'☀ Claro':'☾ Oscuro'}</button>{(profile.role==='admin'||profile.role==='manager')&&<button className="secondary-button" disabled={!online} onClick={sync}>Forzar resincronización (emergencia)</button>}</div></section><section className="action-grid">{actions.map(([icon,title,sub,id])=><button className="action-card" onClick={()=>go(id)} key={id}><span className="action-icon">{icon}</span><span><strong>{title}</strong><small>{sub}</small></span><b>›</b></button>)}</section><section className="overview"><div className="section-heading"><div><p className="section-kicker">RESUMEN OPERATIVO</p><h2>Estado del almacén</h2></div><span className={data.pending?'saved warning':'saved'}>{data.pending?`↻ ${data.pending} pendientes`:'✓ Todo guardado'}</span></div><div className="stats-grid extended">{stats.map(([label,value,note],i)=><article className={`stat-card stat-${i%4}`} key={label}><span className="stat-label">{label}</span><strong>{value}</strong><small>{note}</small></article>)}</div></section></>}

function Receptions({data,busy,create,openLabels,close}:{data:Snapshot;busy:boolean;create:(v:{reference:string;vehicle?:string;receivedAt:string;expectedPallets:number;notes:string})=>Promise<void>;openLabels:(id:string)=>void;close:(id:string)=>void}){
  const [form,setForm]=useState({reference:'',vehicle:'',receivedAt:new Date().toISOString().slice(0,10),expectedPallets:1,notes:''});const submit=(e:FormEvent)=>{e.preventDefault();void create(form)};
  return <Page title="Recepciones" kicker="DESCARGAS Y CONTENEDORES"><form className="panel form-grid reception-form" onSubmit={submit}><Field label="Referencia *"><input required minLength={3} value={form.reference} onChange={e=>setForm({...form,reference:e.target.value.toUpperCase()})} placeholder="REC-2026-001"/></Field><Field label="Matrícula / transporte"><input value={form.vehicle} onChange={e=>setForm({...form,vehicle:e.target.value.toUpperCase()})} placeholder="1234-ABC"/></Field><Field label="Fecha de recepción *"><input required type="date" value={form.receivedAt} onChange={e=>setForm({...form,receivedAt:e.target.value})}/></Field><Field label="Nº de palés *"><input required type="number" min="1" max="500" value={form.expectedPallets} onChange={e=>setForm({...form,expectedPallets:Number(e.target.value)})}/></Field><Field label="Observaciones"><input value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})} placeholder="Información de la descarga"/></Field><button disabled={busy} className="primary-button wide">＋ Crear y generar etiquetas P1–P{form.expectedPallets}</button></form><section className="panel"><div className="section-heading"><h3>Recepciones registradas</h3><span className="count-badge">{data.receptions.length}</span></div>{data.receptions.length===0?<Empty text="Todavía no hay recepciones."/>:<div className="card-list">{[...data.receptions].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(r=>{const count=data.pallets.filter(p=>p.receptionId===r.id&&p.status!=='pendiente').length;const progress=Math.min(100,Math.round(count/r.expectedPallets*100));return <article className="record-card" key={r.id}><div><span className={`status status-${r.status}`}>{r.status}</span><h3>{r.reference}</h3><p>{r.vehicle||'Sin matrícula'} · {new Date((r.receivedAt||r.createdAt)+'T00:00:00').toLocaleDateString('es-ES')} · {r.expectedPallets} palés</p></div><div className="progress"><span style={{width:`${progress}%`}}/><small>{count} de {r.expectedPallets} iniciados</small></div><div className="record-actions"><button className="secondary-button" onClick={()=>openLabels(r.id)}>QR / etiquetas</button>{r.status!=='cerrada'&&<button className="secondary-button danger" onClick={()=>close(r.id)}>Cerrar</button>}</div></article>})}</div>}</section></Page>}

function LabelsView({receptions,pallets,selectedId,onSelect}:{receptions:Reception[];pallets:Pallet[];selectedId:string;onSelect:(id:string)=>void}){
  const [format,setFormat]=useState<'roll'|'a4'>('roll');const [from,setFrom]=useState(1);const [to,setTo]=useState(500);const [codes,setCodes]=useState<Record<string,string>>({});
  const reception=receptions.find(r=>r.id===selectedId)||receptions[0];const items=pallets.filter(p=>p.receptionId===reception?.id&&p.number>=from&&p.number<=to).sort((a,b)=>a.number-b.number);
  // eslint-disable-next-line react-hooks/exhaustive-deps -- regenerar sólo cuando cambia el lote estable.
  useEffect(()=>{let live=true;void Promise.all(items.map(async p=>[p.id,await QRCode.toDataURL(p.code,{width:420,margin:1,errorCorrectionLevel:'M'})] as const)).then(entries=>{if(live)setCodes(Object.fromEntries(entries))});return()=>{live=false}},[reception?.id,from,to,pallets.length]);
  if(!reception)return <Page title="Etiquetas QR" kicker="IDENTIFICACIÓN PREVIA DE PALÉS"><Empty text="Crea una recepción para generar las etiquetas P1, P2, P3…"/></Page>;
  return <Page title="Etiquetas QR" kicker="ROLLO 100 × 64 MM O PAPEL A4"><section className="panel label-controls"><Field label="Recepción"><select value={reception.id} onChange={e=>onSelect(e.target.value)}>{receptions.map(r=><option value={r.id} key={r.id}>{r.reference} · {r.expectedPallets} palés</option>)}</select></Field><Field label="Formato"><select value={format} onChange={e=>setFormat(e.target.value as 'roll'|'a4')}><option value="roll">Rollo 100 × 64 mm</option><option value="a4">A4 (2 por fila)</option></select></Field><Field label="Desde P"><input type="number" min="1" max={reception.expectedPallets} value={from} onChange={e=>setFrom(Number(e.target.value))}/></Field><Field label="Hasta P"><input type="number" min="1" max={reception.expectedPallets} value={Math.min(to,reception.expectedPallets)} onChange={e=>setTo(Number(e.target.value))}/></Field><button className="primary-button" onClick={()=>print()}>Imprimir {items.length} etiquetas</button></section><p className="print-help">En la impresora selecciona escala 100 % y sin márgenes. Puedes imprimirlas antes de empezar a escanear las cajas.</p><section className={`label-sheet format-${format}`}>{items.map(p=><article className="pallet-label" key={p.id}><div className="label-copy"><p>PALLETFLOW · {reception.reference}</p><strong>P{p.number}</strong><span>{p.code}</span><dl><div><dt>Recepción</dt><dd>{new Date((reception.receivedAt||reception.createdAt)+'T00:00:00').toLocaleDateString('es-ES')}</dd></div><div><dt>Matrícula</dt><dd>{reception.vehicle||'—'}</dd></div></dl></div>{codes[p.id]&&<img src={codes[p.id]} alt={`Código QR del palé P${p.number}`}/>}<small>PALLETFLOW ALMACÉN</small></article>)}</section></Page>;
}

function Scanner({pallets,parcels,busy,scan}:{pallets:Pallet[];parcels:Parcel[];busy:boolean;scan:(v:{palletId:string;code:string;article:string;mocacota?:string;color?:string;size?:string;units:number;acceptAnomaly?:boolean})=>Promise<void>}){
  const [palletId,setPallet]=useState('');const [camera,setCamera]=useState<'pallet'|'box'|null>(null);const [switchCode,setSwitchCode]=useState('');const [,setAnomaly]=useState('');const [rule,setRule]=useState(defaultBarcodeRule);const [form,setForm]=useState({code:'',article:'',mocacota:'',color:'',size:'',units:1});const selected=pallets.find(p=>p.id===palletId);const recent=parcels.filter(p=>p.palletId===palletId).slice(-6).reverse();
  useEffect(()=>{const load=()=>setRule(readBarcodeRule());void refreshBarcodeRule().then(setRule);load();addEventListener('palletflow-rule-change',load);return()=>removeEventListener('palletflow-rule-change',load)},[]);
  const setBoxCode=(code:string)=>{const parsed=parseBoxBarcode(code,rule);setForm(f=>({...f,code:parsed.code,article:parsed.mocacota,mocacota:parsed.mocacota,units:parsed.valid?parsed.units:f.units}))};
  const acceptPallet=(code:string)=>{const found=pallets.find(p=>p.code.toUpperCase()===code.toUpperCase());if(found)setPallet(found.id);else alert('Ese QR no corresponde a un palé activo.')};
  const save=async(acceptAnomaly=false)=>{try{await scan({palletId,...form,acceptAnomaly});setForm(f=>({...f,code:''}));setAnomaly('')}catch(error){const message=error instanceof Error?error.message:'No se pudo guardar.';if(message.startsWith('ANOMALY:')){const detail=message.slice(8);setAnomaly(detail);if(confirm(`ANOMALÍA\n\n${detail}\n\nAceptar = Sí, está bien\nCancelar = No, descartar`))void save(true);else setForm(f=>({...f,code:''}))}else alert(message)}};const submit=(e:FormEvent)=>{e.preventDefault();const next=pallets.find(p=>p.code===form.code);if(next){if(switchCode===next.code){setPallet(next.id);setSwitchCode('');setForm(f=>({...f,code:''}));alert(`Palé cambiado a P${next.number}.`)}else{setSwitchCode(next.code);setForm(f=>({...f,code:''}));alert(`Vuelve a escanear ${next.code} para confirmar el cambio de palé.`)}return}setSwitchCode('');void save()};
  return <Page title="Escanear bultos" kicker="QR DEL PALÉ + CÓDIGOS DE LAS CAJAS"><div className="scan-layout"><section className="panel"><div className="step"><b>1</b><span><strong>Escanea el QR del palé</strong><small>También puedes seleccionarlo en la lista.</small></span></div><div className="input-action"><select value={palletId} onChange={e=>setPallet(e.target.value)}><option value="">Seleccionar palé…</option>{pallets.map(p=><option key={p.id} value={p.id}>P{p.number} · {p.code} · {p.parcels} cajas</option>)}</select><button type="button" className="secondary-button" onClick={()=>setCamera('pallet')}>Abrir cámara</button></div>{selected&&<div className="scan-summary"><span>P{selected.number} · {selected.code}</span><strong>{selected.parcels} cajas</strong><strong>{selected.units} unidades</strong></div>}<div className="step"><b>2</b><span><strong>Lee los códigos de las cajas</strong><small>Mocacota y unidades se calculan automáticamente según el código.</small></span></div><form onSubmit={submit}><div className="input-action"><Field label="Código de caja"><input autoFocus inputMode="text" disabled={!selected} value={form.code} onChange={e=>setBoxCode(e.target.value)} placeholder="Escanea o escribe el código"/></Field><button type="button" disabled={!selected} className="secondary-button scan-now" onClick={()=>setCamera('box')}>Cámara</button></div><div className="three-cols"><Field label="Mocacota / artículo"><input disabled={!selected} value={form.mocacota} onChange={e=>setForm({...form,mocacota:e.target.value.toUpperCase(),article:e.target.value.toUpperCase()})}/></Field><Field label="Color / tono"><input disabled={!selected} value={form.color} onChange={e=>setForm({...form,color:e.target.value.toUpperCase()})}/></Field><Field label="Talla"><input disabled={!selected} value={form.size} onChange={e=>setForm({...form,size:e.target.value.toUpperCase()})}/></Field></div><Field label="Unidades en esta caja"><input disabled={!selected} type="number" min="1" value={form.units} onChange={e=>setForm({...form,units:Number(e.target.value)})}/></Field><p className="rule-note">Regla actual: primeros {rule.articleLength} caracteres = mocacota; {rule.unitsLength} dígitos empezando a {rule.unitsFromEnd} del final = unidades.</p><button disabled={!selected||!form.code||!form.mocacota||busy} className="primary-button wide">✓ Guardar caja en P{selected?.number||'—'}</button></form></section><section className="panel"><h3>Últimas lecturas</h3>{recent.length?<div className="scan-list">{recent.map(p=><div key={p.id}><span className={p.anomalous?'dot warning':'dot'}/><strong>{p.code}</strong><small>{p.mocacota||p.article} · {p.color||'sin color'} · {p.size||'sin talla'} · {p.units} uds.</small></div>)}</div>:<Empty text="Selecciona un palé para ver sus cajas."/>}</section></div>{camera&&<CameraScanner formats={camera==='pallet'?['qr_code']:['code_128','ean_13','ean_8','itf','qr_code']} onRead={code=>{camera==='pallet'?acceptPallet(code):setBoxCode(code);setCamera(null)}} onClose={()=>setCamera(null)}/>}</Page>}

function GuidedScanner({pallets,parcels,busy,operator,refresh,tell}:{pallets:Pallet[];parcels:Parcel[];busy:boolean;operator:string;refresh:()=>Promise<void>;tell:(text:string,kind?:'ok'|'error')=>void}){
  const [palletId,setPalletId]=useState('');const [switchCode,setSwitchCode]=useState('');const [camera,setCamera]=useState<'pallet'|'box'|null>(null);const [expected,setExpected]=useState(0);const [rule,setRule]=useState(defaultBarcodeRule);const [form,setForm]=useState({code:'',mocacota:'',color:'',size:'',units:1});const selected=pallets.find(p=>p.id===palletId);const recent=parcels.filter(p=>p.palletId===palletId).slice(-8).reverse();const parsedForm=parseBoxBarcode(form.code,rule);
  useEffect(()=>{const load=()=>setRule(readBarcodeRule());void refreshBarcodeRule().then(setRule);load();addEventListener('palletflow-rule-change',load);return()=>removeEventListener('palletflow-rule-change',load)},[]);
  const choose=(code:string)=>{const clean=code.trim().toUpperCase();const pallet=pallets.find(p=>p.code.toUpperCase()===clean);if(!pallet){tell('Ese QR no corresponde a un palé pendiente.','error');return}if(selected&&selected.id!==pallet.id&&switchCode!==clean){setSwitchCode(clean);tell(`Vuelve a escanear ${pallet.code} para confirmar el cambio.`);return}setSwitchCode('');setPalletId(pallet.id);setExpected(pallet.expectedParcels||0)};
  const setCode=(code:string)=>{const parsed=parseBoxBarcode(code,rule);setForm(f=>({...f,code:parsed.code,mocacota:parsed.mocacota,units:parsed.valid?parsed.units:f.units}))};
  const run=async(action:()=>Promise<unknown>,message:string)=>{try{await action();await refresh();if(navigator.onLine)await syncNow();await refresh();tell(message)}catch(error){const message=error instanceof Error?error.message:'No se pudo guardar.';if(message.startsWith('ANOMALY:')){const detail=message.slice(8);if(confirm(`ANOMALÍA\n\n${detail}\n\nAceptar = Sí, guardar marcada\nCancelar = No, descartar`))await run(()=>scanParcel({palletId,code:form.code,article:form.mocacota,mocacota:form.mocacota,color:form.color,size:form.size,units:form.units,operator,acceptAnomaly:true}),'Caja guardada como anomalía.')}else tell(message,'error')}};
  const saveBox=async(e:FormEvent)=>{e.preventDefault();if(!parsedForm.valid){tell('El código no permite leer una Mocacota y unas unidades válidas con la regla activa.','error');return}await run(()=>scanParcel({palletId,code:form.code,originalCode:form.code,ruleVersion:rule.ruleNumber,article:form.mocacota,mocacota:form.mocacota,color:form.color,size:form.size,units:form.units,operator}),'Caja guardada.');scanFeedback('ok');setForm(f=>({...f,code:''}));requestAnimationFrame(()=>document.querySelector<HTMLInputElement>('[data-box-scanner]')?.focus())};
  return <Page title="Grabar palé" kicker="FLUJO GUIADO SIN SALIR DE LA PANTALLA"><section className="panel guided-scan"><div className="guided-header"><span className={!selected?'current':'done'}>1</span><div><h3>Escanea el QR del palé</h3><p>La etiqueta P1, P2… identifica un único palé.</p></div></div><div className="input-action"><select value={palletId} onChange={e=>setPalletId(e.target.value)}><option value="">Seleccionar palé…</option>{pallets.map(p=><option key={p.id} value={p.id}>P{p.number} · {p.code}</option>)}</select><button className="secondary-button" onClick={()=>setCamera('pallet')}>Abrir cámara QR</button></div>{selected&&<><div className="guided-header"><span className={!selected.expectedParcels?'current':'done'}>2</span><div><h3>¿Cuántas cajas tiene P{selected.number}?</h3><p>Escribe el total físico del palé antes de empezar.</p></div></div><div className="input-action expected-boxes"><input type="number" min={Math.max(1,selected.parcels)} value={expected||''} onChange={e=>setExpected(Number(e.target.value))} placeholder="Ej. 10"/><button className="secondary-button" disabled={!expected} onClick={()=>void run(()=>setExpectedParcels(selected.id,expected,operator),`P${selected.number}: ${expected} cajas previstas.`)}>Confirmar cantidad</button></div>{selected.expectedParcels&&<><div className="scan-progress"><strong>{selected.parcels} / {selected.expectedParcels}</strong><span>Cajas escaneadas</span><progress max={selected.expectedParcels} value={selected.parcels}/></div><div className="guided-header"><span className={selected.parcels<selected.expectedParcels?'current':'done'}>3</span><div><h3>Escanea las cajas una a una</h3><p>Mocacota y unidades se leen automáticamente.</p></div></div><form onSubmit={e=>void saveBox(e)}><div className="input-action"><Field label="Código de caja"><input data-box-scanner autoFocus value={form.code} onChange={e=>setCode(e.target.value)} placeholder="Escanea y pulsa Enter"/></Field><button type="button" className="secondary-button" onClick={()=>setCamera('box')}>Cámara</button><label className="secondary-button file-button">Foto + OCR<input type="file" accept="image/*" capture="environment" onChange={e=>{const file=e.target.files?.[0];if(file)void readOcrFile(file).then(code=>code?setCode(code):tell('No se pudo reconocer un código.','error'))}}/></label></div><div className="three-cols"><Field label="Mocacota"><input value={form.mocacota} onChange={e=>setForm({...form,mocacota:e.target.value.toUpperCase()})}/></Field><Field label="Color"><input value={form.color} onChange={e=>setForm({...form,color:e.target.value.toUpperCase()})}/></Field><Field label="Talla"><input value={form.size} onChange={e=>setForm({...form,size:e.target.value.toUpperCase()})}/></Field></div><Field label="Unidades de esta caja"><input type="number" min="1" value={form.units} onChange={e=>setForm({...form,units:Number(e.target.value)})}/></Field><small className="saved">Guardado automático al pulsar Enter · el foco vuelve al lector</small></form><button className="complete-pallet" disabled={selected.parcels!==selected.expectedParcels||busy} onClick={()=>void run(async()=>{await closePallet(selected.id,operator);scanFeedback('complete');setPalletId('')},`P${selected.number} completo. Ya está pendiente de ubicar.`)}>✓ Cerrar palé como completo</button></>}</>}</section><section className="panel"><h3>Lecturas de este palé</h3>{recent.length?<div className="scan-list">{recent.map(box=><div key={box.id}><span className={box.anomalous?'dot warning':'dot'}/><strong>{box.code}</strong><small>{box.mocacota||box.article} · {box.units} uds.</small></div>)}</div>:<Empty text="Escanea un QR para empezar."/>}</section>{camera&&<CameraScanner formats={camera==='pallet'?['qr_code']:['code_128','ean_13','ean_8','itf','qr_code']} onRead={code=>{camera==='pallet'?choose(code):setCode(code);setCamera(null)}} onClose={()=>setCamera(null)}/>}</Page>;
}

function ReceptionControl({receptions,pallets,locations,operator,act}:{receptions:Reception[];pallets:Pallet[];locations:Location[];operator:string;act:(action:()=>Promise<unknown>,message:string)=>void}){return <section className="panel manager-control"><p className="section-kicker">CONTROL DE ADMINISTRADOR</p><h3>Editar, cerrar y desbloquear recepciones</h3><div className="control-list">{receptions.map(reception=>{const rows=pallets.filter(p=>p.receptionId===reception.id);const complete=rows.filter(p=>p.scanClosedAt).length;const located=rows.filter(p=>p.status==='ubicado').length;return <article key={reception.id}><div><strong>{reception.reference}</strong><span>{complete}/{rows.length} completos · {located}/{rows.length} ubicados · {locations.filter(l=>rows.some(p=>p.locationId===l.id)).length} huecos</span></div><span className={`status status-${reception.status}`}>{reception.status}</span>{reception.status!=='cerrada'?<button className="primary-button" disabled={complete!==rows.length||located!==rows.length} onClick={()=>act(()=>closeReception(reception.id),'Camión cerrado y bloqueado.')}>Cerrar camión</button>:!reception.extractionUnlockedAt?<button className="secondary-button" onClick={()=>act(()=>unlockReceptionForExtraction(reception.id),'Camión desbloqueado para órdenes de extracción.')}>Desbloquear extracción</button>:<span className="saved">Extracción autorizada</span>}<details><summary>Editar recepción y nº de palés</summary><ReceptionEditor reception={reception} operator={operator} act={act}/></details><details><summary>Correcciones de palés</summary>{rows.filter(p=>p.scanClosedAt&&p.status!=='extraido').map(p=><button key={p.id} className="text-button" onClick={()=>act(()=>reopenPallet(p.id,operator),'Lectura del palé reabierta.')}>Reabrir P{p.number}</button>)}</details></article>})}</div></section>}

function ReceptionEditor({reception,operator,act}:{reception:Reception;operator:string;act:(action:()=>Promise<unknown>,message:string)=>void}){const [form,setForm]=useState({reference:reception.reference,vehicle:reception.vehicle||'',receivedAt:reception.receivedAt,expectedPallets:reception.expectedPallets,notes:reception.notes});const save=(e:FormEvent)=>{e.preventDefault();if(!confirm(`Guardar cambios en ${reception.reference} y dejar ${form.expectedPallets} palés activos?`))return;act(()=>updateReception({id:reception.id,...form},operator),'Recepción y cantidad de palés actualizadas.')};return <form className="form-grid compact reception-editor" onSubmit={save}><Field label="Referencia"><input required minLength={3} value={form.reference} onChange={e=>setForm({...form,reference:e.target.value.toUpperCase()})}/></Field><Field label="Matrícula / transporte"><input value={form.vehicle} onChange={e=>setForm({...form,vehicle:e.target.value.toUpperCase()})}/></Field><Field label="Fecha"><input required type="date" value={form.receivedAt} onChange={e=>setForm({...form,receivedAt:e.target.value})}/></Field><Field label="Número de palés"><input required type="number" min="1" max="500" value={form.expectedPallets} onChange={e=>setForm({...form,expectedPallets:Number(e.target.value)})}/></Field><Field label="Observaciones"><input value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field><button className="secondary-button" disabled={reception.status==='cerrada'}>Guardar cambios</button>{reception.status==='cerrada'&&<small>La recepción está cerrada: desbloquéala antes de editar.</small>}</form>}

function TasksView({pallets,locations,operator,busy,complete}:{pallets:Pallet[];locations:Location[];operator:string;busy:boolean;complete:(p:string,l:string,pc:string,c:string)=>void}){const mine=pallets.filter(p=>p.taskStatus==='pendiente'&&(operator.toLowerCase()==='ayyoub'||p.taskAssignee?.toLowerCase()===operator.toLowerCase()));const done=pallets.filter(p=>p.taskStatus==='completada'&&(operator.toLowerCase()==='ayyoub'||p.taskAssignee?.toLowerCase()===operator.toLowerCase()));const [id,setId]=useState('');const [camera,setCamera]=useState<'location1'|'pallet'|'location2'|null>(null);const [form,setForm]=useState({location1:'',pallet:'',location2:''});const task=mine.find(p=>p.id===id);const location=locations.find(l=>l.id===task?.locationId);const read=(value:string)=>{const code=value.trim().toUpperCase();setForm(f=>camera==='pallet'?{...f,pallet:code}:camera==='location2'?{...f,location2:code}:{...f,location1:code})};return <Page title="Tareas de extracción" kicker="LISTA GUIADA PARA OPERARIOS"><section className="panel task-list"><div className="section-heading"><div><h3>Pendientes</h3><p>Ve a la ubicación indicada y completa las tres comprobaciones.</p></div><span className="count-badge">{mine.length}</span></div>{mine.length?mine.map(p=><button key={p.id} className={id===p.id?'task-card selected':'task-card'} onClick={()=>{setId(p.id);setForm({location1:'',pallet:'',location2:''})}}><span>P{p.number}</span><strong>{locations.find(l=>l.id===p.locationId)?.code||'Sin ubicación'}</strong><small>{p.mocacota||p.article} · {p.units} uds.</small></button>):<Empty text="No tienes tareas pendientes."/>}</section>{task&&location&&<section className="panel task-check"><h3>Extraer P{task.number} de {location.code}</h3><div className="task-steps"><Field label="1 · Escanea la ubicación antes de tocar el palé"><div className="input-action"><input value={form.location1} onChange={e=>setForm({...form,location1:e.target.value.toUpperCase()})}/><button className="secondary-button" onClick={()=>setCamera('location1')}>Cámara</button></div></Field><Field label="2 · Escanea el QR del palé"><div className="input-action"><input value={form.pallet} onChange={e=>setForm({...form,pallet:e.target.value.toUpperCase()})}/><button className="secondary-button" onClick={()=>setCamera('pallet')}>Cámara</button></div></Field><Field label="3 · Confirma otra vez la ubicación"><div className="input-action"><input value={form.location2} onChange={e=>setForm({...form,location2:e.target.value.toUpperCase()})}/><button className="secondary-button" onClick={()=>setCamera('location2')}>Cámara</button></div></Field></div><button className="primary-button wide" disabled={busy||!form.location1||!form.pallet||!form.location2} onClick={()=>{complete(task.id,form.location1,form.pallet,form.location2);setId('')}}>Confirmar salida a suelo</button></section>}<section className="panel"><h3>Extraídos a suelo</h3>{done.length?<div className="scan-list">{done.map(p=><div key={p.id}><span className="dot"/><strong>P{p.number} · {p.code}</strong><small>{new Date(p.floorAt||p.updatedAt).toLocaleString('es-ES')}</small></div>)}</div>:<Empty text="Todavía no has completado extracciones."/>}</section>{camera&&<CameraScanner formats={camera==='pallet'?['qr_code']:['qr_code','code_128']} onRead={code=>{read(code);setCamera(null)}} onClose={()=>setCamera(null)}/>}</Page>}

function AdminOrdersPanel({pallets,locations,operator,act}:{pallets:Pallet[];locations:Location[];operator:string;act:(ids:string[],assignee:string)=>void}){const [query,setQuery]=useState('');const [units,setUnits]=useState(1);const [assignee,setAssignee]=useState('');const eligible=pallets.filter(p=>p.status==='ubicado'&&!p.taskStatus);const plan=planPallets(eligible,locations,query,units);return <section className="panel admin-orders"><p className="section-kicker">CREAR ORDEN DE EXTRACCIÓN</p><h3>Asignar palés a un operario</h3><div className="form-grid compact"><Field label="Mocacota"><input value={query} onChange={e=>setQuery(e.target.value.toUpperCase())}/></Field><Field label="Unidades solicitadas"><input type="number" min="1" value={units} onChange={e=>setUnits(Number(e.target.value))}/></Field><Field label="Asignar a"><input value={assignee} onChange={e=>setAssignee(e.target.value)} placeholder="Ej. Manuel"/></Field></div>{query&&<div className="order-preview"><strong>{plan.lines.length} palés · {plan.total} unidades</strong>{plan.lines.map(line=><span key={line.pallet.id}>P{line.pallet.number} · {line.location?.code||'Sin ubicar'} · {line.units} uds.</span>)}</div>}<button className="primary-button" disabled={!assignee||!query||plan.missing>0||!plan.lines.length} onClick={()=>act(plan.lines.map(l=>l.pallet.id),assignee)}>Crear tarea para {assignee||'operario'}</button><small>Antes, desbloquea para extracción el camión correspondiente desde Recepciones.</small></section>}

function LocationsView({pallets,locations,busy,locate,create}:{pallets:Pallet[];locations:Location[];busy:boolean;locate:(p:string,l:string)=>void;create:(v:{code:string;zone:string;aisle:string;module:string;level:string;slot:string;capacity:number;multiple:boolean})=>void}){
  const [palletId,setPallet]=useState('');const [locationId,setLocation]=useState('');const [camera,setCamera]=useState<'pallet'|'location'|null>(null);const [showCreate,setShowCreate]=useState(false);const [f,setF]=useState({code:'',zone:'A',aisle:'01',module:'01',level:'01',slot:'01',capacity:1,multiple:false});
  const accept=(kind:'pallet'|'location',code:string)=>{if(kind==='pallet'){const found=pallets.find(p=>p.code.toUpperCase()===code.toUpperCase());if(found)setPallet(found.id);else alert('Palé no encontrado.')}else{const found=locations.find(l=>l.code.toUpperCase()===code.toUpperCase());if(found)setLocation(found.id);else alert('Ubicación no encontrada.')}};
  return <Page title="Ubicar palé" kicker="ESCANEA QR DEL PALÉ Y CÓDIGO DE UBICACIÓN"><div className="flow-grid"><section className="panel flow-step"><span className="step-number">1</span><h3>Escanea el palé</h3><select value={palletId} onChange={e=>setPallet(e.target.value)}><option value="">Seleccionar palé…</option>{pallets.map(p=><option key={p.id} value={p.id}>P{p.number} · {p.code} · {p.status}</option>)}</select><button className="camera-button" onClick={()=>setCamera('pallet')}>▣ Abrir cámara para QR</button>{palletId&&<strong className="confirmed">✓ Palé preparado</strong>}</section><section className="panel flow-step"><span className="step-number">2</span><h3>Escanea la ubicación</h3><select value={locationId} onChange={e=>setLocation(e.target.value)}><option value="">Seleccionar ubicación…</option>{locations.map(l=><option key={l.id} value={l.id} disabled={l.status!=='disponible'&&!l.multiple}>{l.code} · {l.status}</option>)}</select><button className="camera-button" onClick={()=>setCamera('location')}>▣ Abrir cámara para ubicación</button>{locationId&&<strong className="confirmed">✓ Ubicación válida</strong>}</section></div><button className="primary-button confirm-move" disabled={!palletId||!locationId||busy} onClick={()=>locate(palletId,locationId)}>Confirmar movimiento</button><button className="text-button" onClick={()=>setShowCreate(!showCreate)}>＋ {showCreate?'Ocultar maestro':'Añadir nueva ubicación'}</button>{showCreate&&<form className="panel form-grid compact" onSubmit={e=>{e.preventDefault();create(f)}}>{(['code','zone','aisle','module','level','slot'] as const).map(key=><Field key={key} label={{code:'Código',zone:'Zona',aisle:'Pasillo',module:'Módulo',level:'Nivel',slot:'Hueco'}[key]}><input value={f[key]} required onChange={e=>setF({...f,[key]:e.target.value.toUpperCase()})}/></Field>)}<Field label="Capacidad"><input type="number" min="1" value={f.capacity} onChange={e=>setF({...f,capacity:Number(e.target.value)})}/></Field><label className="check"><input type="checkbox" checked={f.multiple} onChange={e=>setF({...f,multiple:e.target.checked})}/> Permitir varios palés</label><button className="primary-button">Guardar ubicación</button></form>}{camera&&<CameraScanner formats={camera==='pallet'?['qr_code']:['qr_code','code_128']} onRead={code=>{accept(camera,code);setCamera(null)}} onClose={()=>setCamera(null)}/>}</Page>}

function Extraction({pallets,busy,extract}:{pallets:Pallet[];busy:boolean;extract:(p:string,c:number,r:string)=>void}){const [id,setId]=useState('');const pallet=pallets.find(p=>p.id===id);const [count,setCount]=useState(1);const [reason,setReason]=useState('Salida de almacén');return <Page title="Extraer mercancía" kicker="SALIDA TOTAL O PARCIAL"><section className="panel narrow"><Field label="Palé"><select value={id} onChange={e=>{setId(e.target.value);setCount(1)}}><option value="">Seleccionar palé…</option>{pallets.map(p=><option key={p.id} value={p.id}>{p.code} · {p.parcels} bultos</option>)}</select></Field>{pallet&&<div className="big-summary"><span>Disponible</span><strong>{pallet.parcels} bultos</strong><small>{pallet.units} unidades · {pallet.article}</small></div>}<Field label="Bultos a extraer"><input type="number" min="1" max={pallet?.parcels||1} value={count} onChange={e=>setCount(Number(e.target.value))}/></Field><Field label="Motivo obligatorio"><textarea value={reason} onChange={e=>setReason(e.target.value)} rows={3}/></Field><button className="primary-button danger-solid wide" disabled={!pallet||busy} onClick={()=>{if(confirm(`¿Confirmar la extracción de ${count} bultos?`))extract(id,count,reason)}}>Confirmar extracción</button></section></Page>}

function Inventory({pallets,receptions,locations}:{pallets:Pallet[];receptions:Reception[];locations:Location[]}){const [query,setQuery]=useState('');const [status,setStatus]=useState('');const [need,setNeed]=useState(100);const [planQuery,setPlanQuery]=useState('');const [planned,setPlanned]=useState(false);const [qr,setQr]=useState<{code:string;url:string}|null>(null);const filtered=useMemo(()=>pallets.filter(p=>(!status||p.status===status)&&[p.code,p.article,p.mocacota,p.color,p.size,p.operator,locations.find(l=>l.id===p.locationId)?.code,receptions.find(r=>r.id===p.receptionId)?.reference].some(v=>v?.toLowerCase().includes(query.toLowerCase()))),[pallets,query,status,locations,receptions]);const plan=useMemo(()=>planPallets(pallets,locations,planQuery,need),[pallets,locations,planQuery,need]);const showQr=async(p:Pallet)=>setQr({code:p.code,url:await QRCode.toDataURL(p.code,{width:280,margin:2})});return <Page title="Inventario" kicker="BUSCAR PRENDAS Y CALCULAR PALÉS"><section className="panel pick-planner"><div><p className="section-kicker">QUÉ NECESITO COGER</p><h3>Preparar unidades de una prenda</h3><p>Indica la mocacota, artículo, color o talla y te diremos qué palés coger.</p></div><Field label="Mocacota / artículo / color / talla"><input value={planQuery} onChange={e=>{setPlanQuery(e.target.value.toUpperCase());setPlanned(false)}} placeholder="Ej. 841780162002 o AZUL"/></Field><Field label="Unidades necesarias"><input type="number" min="1" value={need} onChange={e=>{setNeed(Number(e.target.value));setPlanned(false)}}/></Field><button className="primary-button" disabled={!planQuery||need<1} onClick={()=>setPlanned(true)}>Calcular palés</button></section>{planned&&<section className="panel pick-result"><div className="section-heading"><div><h3>{plan.lines.length} palés recomendados</h3><p>{plan.total} unidades disponibles para cubrir {need}{plan.total>need?` · sobran ${plan.total-need}`:''}</p></div><span className={plan.missing?'status status-blocked':'saved'}>{plan.missing?`Faltan ${plan.missing} uds.`:'✓ Cantidad cubierta'}</span></div>{plan.lines.length?<ol>{plan.lines.map(line=><li key={line.pallet.id}><strong>P{line.pallet.number} · {line.pallet.code}</strong><span>{line.pallet.mocacota||line.pallet.article} · {line.pallet.color||'sin color'} · {line.pallet.size||'sin talla'}</span><b>{line.units} uds.</b><em>{line.location?.code||'Sin ubicar'}</em></li>)}</ol>:<Empty text="No hay existencias que coincidan."/>}</section>}<section className="panel filters"><input aria-label="Buscar inventario" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar palé, mocacota, color, talla, ubicación…"/><select aria-label="Filtrar por estado" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos los estados</option>{['pendiente','escaneado','ubicado','extraido'].map(s=><option key={s}>{s}</option>)}</select><strong>{filtered.length} resultados</strong></section><section className="panel table-wrap"><table><thead><tr><th>Palé</th><th>Estado</th><th>Mocacota / prenda</th><th>Cajas</th><th>Unidades</th><th>Ubicación</th><th></th></tr></thead><tbody>{filtered.map(p=><tr key={p.id}><td><strong>P{p.number} · {p.code}</strong><small>{receptions.find(r=>r.id===p.receptionId)?.reference}</small></td><td><span className={`status status-${p.status}`}>{p.status}</span></td><td>{p.mocacota||p.article||'—'}<small>{[p.color,p.size].filter(Boolean).join(' · ')}</small></td><td>{p.parcels}</td><td>{p.units}</td><td>{locations.find(l=>l.id===p.locationId)?.code||'—'}</td><td><button className="icon-button" onClick={()=>void showQr(p)} aria-label={`Etiqueta QR de ${p.code}`}>QR</button></td></tr>)}</tbody></table>{!filtered.length&&<Empty text="No hay resultados con esos filtros."/>}</section>{qr&&<div className="modal" role="dialog" aria-modal="true"><div className="label-card"><button className="modal-close" onClick={()=>setQr(null)}>×</button><p>PALLETFLOW LAB · PRUEBAS</p><img src={qr.url} alt={`QR ${qr.code}`}/><h2>{qr.code}</h2><button className="primary-button" onClick={()=>print()}>Imprimir etiqueta</button></div></div>}</Page>}

function MovementsView({movements,pallets,locations}:{movements:Movement[];pallets:Pallet[];locations:Location[]}){return <Page title="Movimientos" kicker="HISTÓRICO INALTERABLE"><section className="panel timeline">{movements.length?movements.map(m=><article key={m.id}><span className="timeline-icon">{m.type==='extraccion'?'↗':m.type==='escaneo'?'▦':'⌖'}</span><div><span className={`status status-${m.type}`}>{m.type}</span><h3>{pallets.find(p=>p.id===m.palletId)?.code||'Palé'}</h3><p>{m.reason}{m.toLocationId?` · destino ${locations.find(l=>l.id===m.toLocationId)?.code}`:''}</p><small>{new Date(m.createdAt).toLocaleString('es-ES')} · {m.operator}</small></div></article>):<Empty text="Aún no hay movimientos."/>}</section></Page>}

function HistoryExplorer({receptions,pallets,parcels}:{receptions:Reception[];pallets:Pallet[];parcels:Parcel[]}){const [query,setQuery]=useState('');const [from,setFrom]=useState('');const [to,setTo]=useState('');const rows=parcels.filter(box=>{const pallet=pallets.find(p=>p.id===box.palletId);const reception=receptions.find(r=>r.id===pallet?.receptionId);const haystack=[box.code,box.mocacota,box.article,box.color,box.size,pallet?.code,reception?.reference,reception?.vehicle].join(' ').toLowerCase();return haystack.includes(query.toLowerCase())&&(!from||box.createdAt.slice(0,10)>=from)&&(!to||box.createdAt.slice(0,10)<=to)});const download=()=>void exportFilteredHistory(rows,receptions,pallets);return <><section className="page-title"><p className="section-kicker">CAMIONES → PALÉS → CAJAS</p><h2>Histórico consultable</h2></section><section className="panel history-filters"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar camión, matrícula, palé, caja o mocacota…"/><Field label="Desde"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Hasta"><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field><button className="secondary-button" disabled={!rows.length} onClick={download}>Descargar lo filtrado (Excel)</button></section><section className="panel history-tree"><div className="section-heading"><h3>{rows.length} cajas · {rows.reduce((sum,row)=>sum+row.units,0)} unidades</h3></div>{receptions.map(reception=>{const receptionPallets=pallets.filter(p=>p.receptionId===reception.id&&rows.some(b=>b.palletId===p.id));if(!receptionPallets.length)return null;return <details key={reception.id} open><summary><strong>{reception.reference}</strong> · {reception.vehicle||'sin matrícula'} · {receptionPallets.reduce((sum,p)=>sum+p.units,0)} uds.</summary>{receptionPallets.map(pallet=><details key={pallet.id}><summary>P{pallet.number} · {pallet.code} · {pallet.parcels} cajas · {pallet.units} uds.</summary><ul>{rows.filter(b=>b.palletId===pallet.id).map(box=><li key={box.id}><strong>{box.code}</strong><span>{box.mocacota||box.article} · {box.color||'—'} · {box.size||'—'}</span><b>{box.units} uds.</b></li>)}</ul></details>)}</details>})}</section></>}

function DataView({busy,pending,onRefresh,tell}:{busy:boolean;pending:number;onRefresh:()=>Promise<void>;tell:(t:string,k?:'ok'|'error')=>void}){const file=async(e:React.ChangeEvent<HTMLInputElement>)=>{const chosen=e.target.files?.[0];if(!chosen)return;if(!confirm('La restauración sustituirá los datos locales. Se descargará antes una copia automática.'))return;try{await restoreBackup(await chosen.text());await onRefresh();tell('Copia restaurada y validada.')}catch{tell('El archivo no es una copia válida de PalletFlow Almacén.','error')}};return <Page title="Datos y copias" kicker="CONTROL LOCAL Y SINCRONIZACIÓN"><div className="data-grid"><section className="panel"><h3>Datos ficticios</h3><p>Carga registros simulados para formación. Estarán marcados como demostración.</p><div className="row-actions"><button className="primary-button" disabled={busy} onClick={()=>void loadDemoData().then(onRefresh).then(()=>tell('Demostración cargada.'))}>Cargar demostración</button><button className="secondary-button danger" onClick={()=>{if(confirm('¿Borrar todos los datos de demostración?'))void clearDemoData().then(onRefresh).then(()=>tell('Demostración eliminada.'))}}>Borrar demostración</button></div></section><section className="panel"><h3>Exportar inventario</h3><p>Archivos protegidos frente a fórmulas maliciosas.</p><div className="row-actions"><button className="secondary-button" onClick={()=>void exportCsv()}>CSV</button><button className="secondary-button" onClick={()=>void exportExcel()}>Excel</button></div></section><section className="panel"><h3>Copia de seguridad</h3><p>Incluye recepciones, palés, bultos, ubicaciones y movimientos.</p><div className="row-actions"><button className="secondary-button" onClick={()=>void createBackup(true)}>Descargar JSON</button><label className="secondary-button file-button">Restaurar JSON<input type="file" accept="application/json" onChange={e=>void file(e)}/></label></div></section><section className="panel"><h3>Cola de sincronización</h3><div className="big-summary"><strong>{pending}</strong><small>operaciones pendientes</small></div><button className="primary-button" onClick={()=>void syncNow().then(onRefresh).then(()=>tell('Sincronización completada.')).catch(e=>tell(e.message,'error'))}>Forzar resincronización (emergencia)</button></section></div></Page>}

function UsersView({current,tell}:{current:Profile;tell:(t:string,k?:'ok'|'error')=>void}){const [users,setUsers]=useState<Profile[]>([]);const [form,setForm]=useState<{email:string;displayName:string;role:Role;permissions:Permission[]}>({email:'',displayName:'',role:'operario',permissions:['recepciones','escanear','ubicar','inventario']});const load=useCallback(()=>fetch('/api/users').then(r=>r.json() as Promise<{users?:Profile[]}>).then(b=>setUsers(b.users||[])).catch(()=>tell('No se pudieron cargar los usuarios.','error')),[tell]);useEffect(()=>{void load()},[load]);const create=async(e:FormEvent)=>{e.preventDefault();const r=await fetch('/api/users',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(form)});const b=await r.json() as {error?:string};if(!r.ok){tell(b.error||'No se pudo crear el perfil.','error');return;}tell('Perfil creado. Ya puede iniciar sesión con ese correo.');setForm({...form,email:'',displayName:''});void load()};const update=async(user:Profile,changes:Partial<Profile>)=>{const next={...user,...changes};const r=await fetch('/api/users',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(next)});const b=await r.json() as {error?:string};if(!r.ok){tell(b.error||'No se pudo actualizar el perfil.','error');return;}tell('Permisos actualizados.');void load()};return <Page title="Usuarios y permisos" kicker="PANEL DE MANAGER"><section className="panel"><h3>Crear perfil</h3><p className="muted">Escribe el mismo correo que la persona utilizará al iniciar sesión.</p><form className="form-grid compact" onSubmit={e=>void create(e)}><Field label="Nombre"><input required value={form.displayName} onChange={e=>setForm({...form,displayName:e.target.value})}/></Field><Field label="Correo"><input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value.toLowerCase()})}/></Field><Field label="Rol"><select value={form.role} onChange={e=>setForm({...form,role:e.target.value as Role})}><option value="operario">Operario</option><option value="coordinador">Coordinador</option><option value="manager">Manager</option></select></Field><fieldset className="permissions"><legend>Permisos</legend>{allPermissions.map(p=><label key={p}><input type="checkbox" checked={form.permissions.includes(p)} onChange={e=>setForm({...form,permissions:e.target.checked?[...form.permissions,p]:form.permissions.filter(x=>x!==p)})}/>{p}</label>)}</fieldset><button className="primary-button">Crear perfil</button></form></section><section className="panel"><div className="section-heading"><h3>Perfiles</h3><span className="count-badge">{users.length}</span></div><div className="user-list">{users.map(user=><article key={user.id}><div className="avatar">{user.displayName.slice(0,2).toUpperCase()}</div><div><h3>{user.displayName}{user.id===current.id?' · Tú':''}</h3><p>{user.email}</p><span className={`status status-${user.status}`}>{user.status}</span></div><select aria-label={`Rol de ${user.displayName}`} value={user.role} onChange={e=>void update(user,{role:e.target.value as Role})} disabled={user.id===current.id}><option value="operario">Operario</option><option value="coordinador">Coordinador</option><option value="manager">Manager</option></select><select aria-label={`Estado de ${user.displayName}`} value={user.status} onChange={e=>void update(user,{status:e.target.value as Profile['status']})} disabled={user.id===current.id}><option value="pending">Pendiente</option><option value="active">Activo</option><option value="blocked">Bloqueado</option></select><details><summary>Permisos</summary><div className="permissions mini">{allPermissions.map(p=><label key={p}><input type="checkbox" checked={user.permissions.includes(p)} onChange={e=>void update(user,{permissions:e.target.checked?[...user.permissions,p]:user.permissions.filter(x=>x!==p)})}/>{p}</label>)}</div></details></article>)}</div></section></Page>}

function CloudBackupPanel({onRefresh,tell}:{onRefresh:()=>Promise<void>;tell:(text:string,kind?:'ok'|'error')=>void}){const [busy,setBusy]=useState(false);const run=async(action:'up'|'down')=>{setBusy(true);try{if(action==='up'){const result=await uploadCloudBackup();await onRefresh();tell(`Copia subida a la nube · ${new Date(result.createdAt||Date.now()).toLocaleString('es-ES')}`)}else{const result=await downloadCloudBackup();await onRefresh();tell(`Copia bajada · guardada por ${result.operator||'otro operario'}`)}}catch(error){tell(error instanceof Error?error.message:'No se pudo completar la copia.','error')}finally{setBusy(false)}};return <section className="panel cloud-backup"><p className="section-kicker">COPIA COMPARTIDA EN LA NUBE</p><h3>Continuar el trabajo desde otro móvil</h3><p><strong>Subir</strong> guarda una copia completa. <strong>Bajar</strong> trae la última copia sin borrar lo que ya tengas en el dispositivo.</p><div className="row-actions"><button className="primary-button" disabled={busy} onClick={()=>void run('up')}>↑ Subir copia a la nube</button><button className="secondary-button" disabled={busy} onClick={()=>void run('down')}>↓ Bajar última copia</button></div></section>}

type DetectorResult={rawValue:string};
function BarcodeSettings({tell}:{tell:(text:string,kind?:'ok'|'error')=>void}){const [rule,setRule]=useState(()=>readBarcodeRule());const [sample,setSample]=useState('84178016200200287');const parsed=parseBoxBarcode(sample,rule);return <section className="panel barcode-settings"><p className="section-kicker">LECTURA DEL CÓDIGO DE BULTO</p><div className="barcode-rule-grid"><Field label="UDS: DÍGITOS DESDE EL FINAL"><input type="number" min="1" max="20" value={rule.unitsFromEnd} onChange={e=>setRule({...rule,unitsFromEnd:Number(e.target.value)})}/></Field><Field label="UDS: Nº DE DÍGITOS"><input type="number" min="1" max="6" value={rule.unitsLength} onChange={e=>setRule({...rule,unitsLength:Number(e.target.value)})}/></Field><Field label="MOCACOTA: PRIMEROS CARACTERES"><input type="number" min="1" max="30" value={rule.articleLength} onChange={e=>setRule({...rule,articleLength:Number(e.target.value)})}/></Field><Field label="PATRÓN DEL CONTENEDOR ACTIVO"><input readOnly value="Sin definir (lo fija el primer bulto válido)"/></Field></div><p className={parsed.valid?'barcode-preview ok':'barcode-preview error'}>Con <strong>{parsed.code||'—'}</strong> → uds. <strong>{parsed.valid?parsed.units:'no válidas'}</strong>, mocacota <strong>{parsed.mocacota||'—'}</strong>.</p><Field label="PROBAR UN CÓDIGO"><input value={sample} onChange={e=>setSample(e.target.value)} placeholder="Pega aquí una etiqueta de bulto"/></Field><button className="primary-button" disabled={!parsed.valid} onClick={()=>{saveBarcodeRule(rule);tell('Reglas guardadas. Los siguientes bultos usarán esta lectura.')}}>Guardar reglas</button></section>}

type DetectorConstructor=new(options:{formats:string[]})=>{detect(source:HTMLVideoElement):Promise<DetectorResult[]>};
function CameraScanner({formats,onRead,onClose}:{formats:string[];onRead:(code:string)=>void;onClose:()=>void}){
  const video=useRef<HTMLVideoElement>(null);const [error,setError]=useState('');const [manual,setManual]=useState('');
  useEffect(()=>{let active=true;let stream:MediaStream|undefined;let timer:number|undefined;let fallbackControl:{stop:()=>void}|undefined;const start=async()=>{try{if(!video.current)return;const Detector=(window as typeof window&{BarcodeDetector?:DetectorConstructor}).BarcodeDetector;if(!Detector){const {BrowserMultiFormatReader}=await import('@zxing/browser');const reader=new BrowserMultiFormatReader();fallbackControl=await reader.decodeFromConstraints({video:{facingMode:{ideal:'environment'}},audio:false},video.current,(result,_error,controls)=>{if(active&&result){controls.stop();onRead(result.getText())}});return}stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(!active)return;video.current.srcObject=stream;await video.current.play();const detector=new Detector({formats});const tick=async()=>{if(!active||!video.current)return;try{const results=await detector.detect(video.current);if(results[0]?.rawValue){onRead(results[0].rawValue);return}}catch{}timer=window.setTimeout(tick,350)};void tick()}catch{setError('No se pudo abrir o iniciar el lector. Revisa el permiso de cámara o escribe el código manualmente.')}};void start();return()=>{active=false;if(timer)clearTimeout(timer);fallbackControl?.stop();stream?.getTracks().forEach(track=>track.stop())}},[formats,onRead]);
  return <div className="modal camera-modal" role="dialog" aria-modal="true"><section className="camera-card"><button className="modal-close" onClick={onClose}>×</button><h2>Apunta al código</h2><p>Coloca el QR o código de barras dentro del recuadro.</p><div className="camera-viewport"><video ref={video} playsInline muted/><i/></div>{error&&<p className="camera-error">{error}</p>}<div className="input-action"><input autoFocus={Boolean(error)} value={manual} onChange={e=>setManual(e.target.value.toUpperCase())} placeholder="Código manual"/><button className="primary-button" disabled={!manual.trim()} onClick={()=>onRead(manual.trim())}>Usar código</button></div></section></div>;
}

function Page({title,kicker,children}:{title:string;kicker:string;children:React.ReactNode}){return <><section className="page-title"><p className="section-kicker">{kicker}</p><h2>{title}</h2></section>{children}</>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Empty({text}:{text:string}){return <div className="empty"><span>□</span><p>{text}</p></div>}
